fn calculate_jungle_action_score(_rnd, player, data, _parameter, _action, effect, t) -> i64   // action_score.rs:520

// --- L522: 내 챔프 얻기 ---
team = player.info.team                       // PlayerState+0x930, usize
if team >= 2 { panic_bounds_check(team, 2) }  // player_champion 이 [_;2] 배열이라
pos  = player.info.position.as_index()        // PlayerState+0x9c0 (i32 0..=4) → usize (entity.rs:580 인라인, 항등변환)
champ = data.cache.player_champion[team][pos] // AbstractGameWithCache+0x1e0, Option<&Entity> (널포인터 니치)
if champ.is_none() { panic!("Option::unwrap on None") }   // option.rs:1011/1013 인라인

// --- L523: 예상 데미지 ---
value: i64 = effect.expected_damage_target(data.context, champ as &dyn AbstractEntity, t)
  // 4번째 IR 인자는 champ 의 vtable(=Entity as AbstractEntity, anon..17). 즉 champ 이 &dyn 로 넘어간다.

// --- L524 ---
hp: i64 = t.hp                                // Entity+0x670

// --- L526~536: 대상 종류별 계수 ---
// 소스에선 is_nexus()/is_jungle() 같은 술어의 else-if 체인이지만, LLVM 에서는
// EntityType 판별자(Entity+0x68) 하나에 대한 switch 로 통째로 접혔다.
// 태그는 모두 서로 배타적이라 소스상의 arm 순서와 무관하게 결과가 확정된다.
coef =
  match t.ty_tag {
    3 /*Nexus*/  => 200,                       // L526  t.ty.is_nexus()
    2 /*Tower*/  => 80,                        // L528
    4 /*Jungle*/ => if t.ty.<Jungle>.info.camp_type.0 < 2 {   // L530  t.ty.is_jungle() (entity.rs:1377-1378), Entity+0x98
                       if hp > value { 20 } else { 40 }       // L531  한 방에 못 잡으면 20, 잡을 수 있으면 40
                    } else { 0 },              // 태그4지만 camp_type.0>=2 → switch default 블록과 합류해 0
    1 /*Minion*/ => -10,                       // L536 근처
    _            => 0,                         // L536  None/Epic/Serpen/Ghoul/SmallJiangshi/Bear/Eagle/Revenant/Illusion/Champion
  }

// --- L542: 정글 보너스 ---
based = if t.ty.is_jungle() { 5 } else { 0 }   // 즉 (tag == 4 && camp_type.0 < 2) ? 5 : 0
  // IR: %53 = icmp eq %29,4 ; %54 = icmp ult %34,2 ; %55 = select %53,%54,false ; %56 = select %55,5,0

// --- L548: 최종식 ---
if hp == 0 { panic!("divide by zero") }        // ★HP 0 인 엔티티가 들어오면 패닉한다(가드 없음)
if hp == -1 && coef*value == i64::MIN { panic!("overflow") }
return (coef * value / hp).min(coef) + based   // L548, Ord::min (cmp.rs:1073/1078) = llvm.smin.i64
// L549 = ret

// 의미: '내 챔프가 이 대상에게 넣을 수 있는 예상딜이 대상 HP 에서 차지하는 비율'을
//       종류별 계수에 곱하되, 계수 자체를 상한으로 clamp 한다(비율 1 이상이어도 coef 초과 불가).
//       coef 가 음수(미니언, -10)면 min 이 반대로 작용해 비율이 클수록 더 큰 음수가 된다.
